# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs]

# region: shape
def shape(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: fold
def fold(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(emit(shape(render(gather(raw)))))

